/**
 * Browser-safe mirror of shared/billQualityRemediation.js for legacy client fallback.
 */
// eslint-disable-next-line @typescript-eslint/no-var-requires
const CARBON_DEFAULTS = require('./carbonEmissionDefaults.json');

const MIN_BILL_QUALITY_FOR_PROCESSING =
  CARBON_DEFAULTS.documentPipeline?.minBillQualityForProcessing ?? 0.65;
const MIN_OCR_ACCURACY_FOR_CARBON_ANALYSIS =
  CARBON_DEFAULTS.documentPipeline?.minOcrAccuracyForCarbonAnalysis ?? 0.75;
const MIN_OCR_ACCURACY_FOR_ACTIVITY_UPLIFT =
  CARBON_DEFAULTS.documentPipeline?.minOcrAccuracyForActivityUplift ?? 0.75;

const INVALID_VENDOR_NAMES = new Set([
  'item',
  'retail vendor',
  'unknown',
  'unknown vendor',
  'n/a',
  'na',
  'tax invoice',
  'digitally signed',
  'original copy'
]);

const buildBillQualityRemediation = ({
  billQuality = 0,
  extractedData = {},
  accuracyReport = null,
  userVerifiedForEmissions = false,
  processingWarnings = []
} = {}) => {
  const quality = Number(billQuality);
  if (!Number.isFinite(quality)) {
    return null;
  }
  if (quality < MIN_BILL_QUALITY_FOR_PROCESSING) {
    return null;
  }
  if (quality >= MIN_OCR_ACCURACY_FOR_CARBON_ANALYSIS) {
    return null;
  }

  const qualityPct = Math.round(quality * 100);
  const carbonThresholdPct = Math.round(MIN_OCR_ACCURACY_FOR_CARBON_ANALYSIS * 100);
  const activityThresholdPct = Math.round(MIN_OCR_ACCURACY_FOR_ACTIVITY_UPLIFT * 100);
  const ocrOverall = Number(accuracyReport?.overall);
  const ocrOverallPct = Number.isFinite(ocrOverall) ? Math.round(ocrOverall * 100) : null;
  const warnText = Array.isArray(processingWarnings)
    ? processingWarnings.map((entry) => String(entry || '')).join(' ')
    : '';

  const suggestions = [
    {
      id: 'verify_extracted_fields',
      severity: 'important',
      message:
        'Confirm vendor name, bill date, GSTIN, and invoice number against the original file, then verify and accept for carbon calculations.',
      action: 'verify'
    },
    {
      id: 'reupload_clearer_scan',
      severity: 'recommended',
      message: `Extraction quality is ${qualityPct}% (target ≥${carbonThresholdPct}%). Upload a clearer scan with readable GSTIN, amounts, and line items.`,
      action: 'reupload'
    }
  ];

  if (Number.isFinite(ocrOverall) && ocrOverall < MIN_OCR_ACCURACY_FOR_CARBON_ANALYSIS) {
    suggestions.push({
      id: 'ocr_agreement_low',
      severity: 'important',
      message: `OCR agreement is about ${ocrOverallPct}% — manually correct line items, tax splits, or dates if they look wrong.`,
      action: 'verify'
    });
  }

  if (!userVerifiedForEmissions) {
    suggestions.push({
      id: 'provisional_inventory',
      severity: 'recommended',
      message:
        'Provisional transactions may be created until you verify and accept this bill for statutory reporting.',
      action: 'verify'
    });
  }

  suggestions.push({
    id: 'activity_uplift_blocked',
    severity: 'info',
    message: `Metered kWh, litres, or kg uplift requires ≥${activityThresholdPct}% OCR — re-upload with visible meter readings or enter activity units manually.`,
    action: 'metered_upload'
  });

  if (/date could not/i.test(warnText) || !extractedData?.date) {
    suggestions.push({
      id: 'confirm_invoice_date',
      severity: 'important',
      message: 'The invoice date is ambiguous or missing — confirm the correct date (watch for DD/MM vs MM/DD).',
      action: 'verify'
    });
  }

  const vendorName = extractedData?.vendor?.name || extractedData?.vendor;
  if (
    !vendorName
    || String(vendorName).toLowerCase() === 'unknown vendor'
    || INVALID_VENDOR_NAMES.has(String(vendorName).toLowerCase())
  ) {
    suggestions.push({
      id: 'confirm_vendor',
      severity: 'recommended',
      message: 'The supplier or vendor name could not be confirmed — attribute this invoice to the correct vendor.',
      action: 'verify'
    });
  }

  if ((extractedData?.category || '').toLowerCase() === 'other') {
    suggestions.push({
      id: 'reclassify_category',
      severity: 'recommended',
      message:
        'Spend category defaulted to “other” — reclassify (e.g. fuel, grid power, freight, raw material).',
      action: 'verify'
    });
  }

  return {
    band: 'review_required',
    qualityScore: Number(quality.toFixed(3)),
    qualityPct,
    minProcessingThreshold: MIN_BILL_QUALITY_FOR_PROCESSING,
    carbonAnalysisThreshold: MIN_OCR_ACCURACY_FOR_CARBON_ANALYSIS,
    activityUpliftThreshold: MIN_OCR_ACCURACY_FOR_ACTIVITY_UPLIFT,
    summary: `Bill processed with spend-based carbon (conservative fallback). Extraction quality is ${qualityPct}% — verify fields or upload a clearer scan to reach ${carbonThresholdPct}%.`,
    suggestions,
    capabilities: {
      processed: true,
      spendCarbon: true,
      activityUplift: Number.isFinite(ocrOverall) && ocrOverall >= MIN_OCR_ACCURACY_FOR_ACTIVITY_UPLIFT,
      requiresVerification: !userVerifiedForEmissions
    },
    legacyFallback: true
  };
};

module.exports = {
  MIN_BILL_QUALITY_FOR_PROCESSING,
  MIN_OCR_ACCURACY_FOR_CARBON_ANALYSIS,
  MIN_OCR_ACCURACY_FOR_ACTIVITY_UPLIFT,
  buildBillQualityRemediation
};
