import type { Document } from '../services/documentService';
import { isExtractedDataVerified } from './extractedDataVerification';

// eslint-disable-next-line @typescript-eslint/no-var-requires
const { buildBillQualityRemediation } = require('../shared/billQualityRemediation.js');

export type BillQualitySuggestionAction =
  | 'verify'
  | 'reupload'
  | 'metered_upload';

export type BillQualitySuggestion = {
  id: string;
  severity: 'important' | 'recommended' | 'info';
  message: string;
  action: BillQualitySuggestionAction;
};

export type BillQualityRemediation = {
  band: 'review_required';
  qualityScore: number;
  qualityPct: number;
  minProcessingThreshold: number;
  carbonAnalysisThreshold: number;
  activityUpliftThreshold: number;
  summary: string;
  suggestions: BillQualitySuggestion[];
  capabilities: {
    processed: boolean;
    spendCarbon: boolean;
    activityUplift: boolean;
    requiresVerification: boolean;
  };
  legacyFallback?: boolean;
};

type DocumentWithRemediation = Pick<
  Document,
  'status' | 'processingResults' | 'extractedDataVerification' | 'extractedData'
> & {
  id?: string;
};

const resolveLegacyBillQualityScore = (document: DocumentWithRemediation): number | null => {
  const confidence = Number(document.processingResults?.confidence);
  const invoiceConfidence = Number(document.extractedData?.ocr_validation?.invoice_confidence);
  const candidates = [confidence, invoiceConfidence].filter(
    (value) => Number.isFinite(value) && value >= 0
  );
  if (candidates.length === 0) {
    return null;
  }
  return Math.min(...candidates);
};

const buildLegacyBillQualityRemediation = (
  document: DocumentWithRemediation
): BillQualityRemediation | null => {
  if (document.status !== 'processed') {
    return null;
  }

  const billQuality = resolveLegacyBillQualityScore(document);
  if (!Number.isFinite(billQuality)) {
    return null;
  }

  const userVerifiedForEmissions = document.extractedDataVerification?.status === 'verified'
    && document.extractedDataVerification?.acceptedForEmissions === true;

  return buildBillQualityRemediation({
    billQuality,
    extractedData: document.extractedData || {},
    accuracyReport: document.processingResults?.accuracyReport || null,
    userVerifiedForEmissions,
    processingWarnings: document.processingResults?.warnings || []
  }) as BillQualityRemediation | null;
};

const MIN_PROCESSING = 0.65;
const MIN_CARBON = 0.75;

export function getBillQualityRemediation(
  document: DocumentWithRemediation
): BillQualityRemediation | null {
  const persisted = document.processingResults?.billQualityRemediation;
  if (persisted && persisted.band === 'review_required') {
    return persisted as BillQualityRemediation;
  }
  return buildLegacyBillQualityRemediation(document);
}

export function isBillQualityReviewBand(document: DocumentWithRemediation): boolean {
  return getBillQualityRemediation(document) != null;
}

export function documentNeedsBillQualityReview(document: DocumentWithRemediation): boolean {
  if (document.status !== 'processed') {
    return false;
  }
  if (isExtractedDataVerified(document)) {
    return false;
  }
  return isBillQualityReviewBand(document);
}

export function findNextBillNeedingReview<T extends DocumentWithRemediation & { id: string; createdAt?: string }>(
  documents: T[],
  afterDocumentId?: string | null
): T | null {
  const candidates = documents
    .filter((doc) => documentNeedsBillQualityReview(doc))
    .sort((a, b) => {
      const aTime = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const bTime = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return aTime - bTime;
    });

  if (candidates.length === 0) {
    return null;
  }

  if (!afterDocumentId) {
    return candidates[0];
  }

  const currentIndex = candidates.findIndex((doc) => doc.id === afterDocumentId);
  if (currentIndex >= 0 && currentIndex < candidates.length - 1) {
    return candidates[currentIndex + 1];
  }
  return candidates.find((doc) => doc.id !== afterDocumentId) || null;
}

export function formatBillQualityBandLabel(remediation: BillQualityRemediation): string {
  return `Review required (${remediation.qualityPct}% · target ≥${Math.round(remediation.carbonAnalysisThreshold * 100)}%)`;
}

export { MIN_PROCESSING, MIN_CARBON };
