import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Grid,
  TextField,
  Typography,
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  Edit as EditIcon,
  Verified as VerifiedIcon,
} from '@mui/icons-material';
import type { Document } from '../services/documentService';
import documentService from '../services/documentService';
import ExtractedBillTransactionsPreview from './ExtractedBillTransactionsPreview';
import {
  getExtractedDataVerificationState,
  getExtractedVerificationFields,
  isExtractedDataVerified,
  shouldShowExtractedDataVerification,
  type ExtractedVerificationFields,
} from '../utils/extractedDataVerification';

export interface ExtractedDataVerificationPanelProps {
  document: Document;
  compact?: boolean;
  onVerified?: (document: Document) => void;
}

const ExtractedDataVerificationPanel: React.FC<ExtractedDataVerificationPanelProps> = ({
  document,
  compact = false,
  onVerified,
}) => {
  const [form, setForm] = useState<ExtractedVerificationFields>(() =>
    getExtractedVerificationFields(document)
  );
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);

  const verificationState = useMemo(
    () => getExtractedDataVerificationState(document),
    [document]
  );
  const verified = isExtractedDataVerified(document);

  useEffect(() => {
    setForm(getExtractedVerificationFields(document));
    setError(null);
    setSuccess(null);
    setWarnings([]);
  }, [document]);

  if (!shouldShowExtractedDataVerification(document)) {
    return null;
  }

  const handleChange = (field: keyof ExtractedVerificationFields, value: string) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    setError(null);
    setSuccess(null);
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    setError(null);
    setSuccess(null);
    setWarnings([]);

    try {
      const response = await documentService.verifyExtractedData(document.id, form);
      if (!response.success) {
        setError(response.message || 'Unable to verify extracted bill data');
        return;
      }

      setSuccess(response.message);
      setWarnings(response.warnings || []);
      onVerified?.(response.document);
    } catch (submitError: unknown) {
      const message = submitError instanceof Error
        ? submitError.message
        : 'Unable to verify extracted bill data';
      setError(message);
    } finally {
      setSubmitting(false);
    }
  };

  const submitLabel = verified
    ? 'Update and accept for carbon calculations'
    : 'Verify and accept for carbon calculations';

  return (
    <Box
      id={document.id ? `bill-verify-${document.id}` : 'bill-verify-panel'}
      sx={{
        mt: compact ? 1.5 : 2,
        p: compact ? 1.5 : 2,
        borderRadius: 1,
        border: '1px solid',
        borderColor: verified ? 'success.light' : 'warning.light',
        bgcolor: verified ? 'success.50' : 'warning.50',
      }}
    >
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1.5, flexWrap: 'wrap' }}>
        {verified ? (
          <VerifiedIcon color="success" fontSize="small" />
        ) : (
          <EditIcon color="warning" fontSize="small" />
        )}
        <Typography variant={compact ? 'subtitle2' : 'subtitle1'} sx={{ fontWeight: 600 }}>
          Review extracted bill data
        </Typography>
        <Chip
          size="small"
          color={verified ? 'success' : 'warning'}
          label={verified ? 'Verified for emissions' : 'Awaiting verification'}
        />
      </Box>

      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Confirm vendor name, date, GSTIN, and invoice number extracted from your upload.
        Bill transaction amounts are shown below for review only and cannot be edited here.
      </Typography>

      <Grid container spacing={2}>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="Vendor name"
            value={form.vendorName}
            onChange={(event) => handleChange('vendorName', event.target.value)}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="Bill date"
            type="date"
            value={form.date}
            onChange={(event) => handleChange('date', event.target.value)}
            InputLabelProps={{ shrink: true }}
            required
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="GSTIN"
            value={form.gstin}
            onChange={(event) => handleChange('gstin', event.target.value.toUpperCase())}
            placeholder="15-character GST number"
            inputProps={{ maxLength: 15 }}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            fullWidth
            size="small"
            label="Invoice number"
            value={form.invoiceNumber}
            onChange={(event) => handleChange('invoiceNumber', event.target.value)}
            required
          />
        </Grid>
      </Grid>

      <ExtractedBillTransactionsPreview document={document} compact={compact} />

      {error && (
        <Alert severity="error" sx={{ mt: 2 }}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mt: 2 }} icon={<CheckCircleIcon fontSize="inherit" />}>
          {success}
          {verificationState.verifiedAt && verified && (
            <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
              Last verified: {new Date(verificationState.verifiedAt).toLocaleString()}
            </Typography>
          )}
        </Alert>
      )}

      {warnings.length > 0 && (
        <Alert severity="warning" sx={{ mt: 2 }}>
          {warnings.map((warning) => (
            <Typography key={warning} variant="body2">
              {warning}
            </Typography>
          ))}
        </Alert>
      )}

      <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
        <Button
          variant="contained"
          color={verified ? 'primary' : 'success'}
          onClick={() => {
            void handleSubmit();
          }}
          disabled={submitting}
          startIcon={submitting ? <CircularProgress size={16} color="inherit" /> : undefined}
        >
          {submitting ? 'Submitting…' : submitLabel}
        </Button>
      </Box>
    </Box>
  );
};

export default ExtractedDataVerificationPanel;
