import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Chip,
  CircularProgress,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from '@mui/material';
import ApiService from '../services/api';
import { formatFixed } from '../utils/formatNumbers';

interface SpamTransaction {
  _id: string;
  description: string;
  amount: number;
  currency?: string;
  date: string;
  source: string;
  spamScore?: number;
  spamConfidence?: number;
  spamReasons?: string[];
  vendor?: { name?: string };
}

const SpamTransactionsPanel: React.FC = () => {
  const [transactions, setTransactions] = useState<SpamTransaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [total, setTotal] = useState(0);

  const loadSpamTransactions = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await ApiService.getSpamTransactions({
        page: page + 1,
        limit: rowsPerPage,
        source: 'sms',
      });
      const data = response?.data;
      setTransactions(Array.isArray(data?.transactions) ? data.transactions : []);
      setTotal(Number(data?.pagination?.total) || 0);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'Unable to load spam transactions.');
      setTransactions([]);
      setTotal(0);
    } finally {
      setLoading(false);
    }
  }, [page, rowsPerPage]);

  useEffect(() => {
    void loadSpamTransactions();
  }, [loadSpamTransactions]);

  const formatDate = (value: string) => {
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? '—' : parsed.toLocaleDateString('en-IN');
  };

  return (
    <Box>
      <Alert severity="info" sx={{ mb: 2 }}>
        These SMS messages were flagged as spam by the mobile classifier and are excluded from your carbon footprint and
        operational transaction totals. Review them here to confirm nothing important was filtered out.
      </Alert>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress size={32} />
        </Box>
      ) : transactions.length === 0 ? (
        <Paper sx={{ p: 3 }}>
          <Typography variant="body2" color="text.secondary">
            No spam-flagged SMS transactions yet. Open the mobile app, run SMS analysis, and sync classified messages to
            populate this list.
          </Typography>
        </Paper>
      ) : (
        <>
          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Date</TableCell>
                  <TableCell>Description</TableCell>
                  <TableCell>Sender / vendor</TableCell>
                  <TableCell align="right">Amount</TableCell>
                  <TableCell>Spam signals</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {transactions.map((transaction) => (
                  <TableRow key={transaction._id} hover>
                    <TableCell>{formatDate(transaction.date)}</TableCell>
                    <TableCell>{transaction.description}</TableCell>
                    <TableCell>{transaction.vendor?.name || '—'}</TableCell>
                    <TableCell align="right">
                      {transaction.currency || 'INR'} {formatFixed(transaction.amount, 2)}
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                        {(transaction.spamReasons || []).slice(0, 3).map((reason) => (
                          <Chip key={`${transaction._id}-${reason}`} size="small" label={reason} color="warning" />
                        ))}
                        {typeof transaction.spamConfidence === 'number' && (
                          <Chip
                            size="small"
                            variant="outlined"
                            label={`${Math.round(transaction.spamConfidence * 100)}% confidence`}
                          />
                        )}
                      </Box>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
          <TablePagination
            component="div"
            count={total}
            page={page}
            onPageChange={(_event, nextPage) => setPage(nextPage)}
            rowsPerPage={rowsPerPage}
            onRowsPerPageChange={(event) => {
              setRowsPerPage(parseInt(event.target.value, 10));
              setPage(0);
            }}
            rowsPerPageOptions={[10, 20, 50]}
          />
        </>
      )}
    </Box>
  );
};

export default SpamTransactionsPanel;
